import{_ as t,l as o,o as e,c as n,v as r,p as d,x as i,d as s,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"GUI 定位","description":"","frontmatter":{"title":"GUI 定位","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/gui-grounding.md","filePath":"llm/gui-grounding.md","lastUpdated":1789023840000}'),h={name:"llm/gui-grounding.md"};function u(g,a,m,_,f,E){const l=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="gui-定位" tabindex="-1">GUI 定位 <a class="header-anchor" href="#gui-定位" aria-label="Permalink to &quot;GUI 定位&quot;">​</a></h1><div class="epigraph"><p>屏幕上的「提交」是一块像素控件，不是自然图里的物体名词。点偏一个图标，动作就错成另一个 API。</p><footer>—— Cheng 等 SeeClick / ScreenSpot；Hong 等 CogAgent</footer></div><p><a href="/llm/grounding-referring">上一课</a>在照片上输出框。缺口是 GUI：截图、图标、文字按钮、多层窗口，目标是可点击的点或控件框，供代理执行。后课图表默认：又一类必须读结构的人造画布，但任务从点击换成读数。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>自然图预训练（<a href="/llm/clip">CLIP</a>、<a href="/llm/vit-as-encoder">ViT</a>）看的是物体与场景。UI 是平面设计：细字、低对比图标、重复列表项，224 squish 会先毁掉可点目标。指令「点击关闭」在不同皮肤下外观不同，必须靠文字、位置与邻近元素，而不是「关闭按钮」这个物体类。</p><p>SeeClick 把 GUI grounding 从代理规划里拆出来：先在截图上把指令落到坐标，再谈规划。ScreenSpot 覆盖移动 / 桌面 / Web，按文本控件与图标分列——图标更难，因为少了 OCR 捷径。CogAgent 用更高分辨率视觉与 GUI 数据训专门的截图理解。</p><p><span class="marginnote">输出点还是框是协议。点击任务常用归一化坐标；框便于调试，但代理最终要一个点。元素 HTML 树若可得，像素 grounding 仍必要：渲染后的真源是截图。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>数据：截图–指令–坐标三元组，覆盖分辨率与主题。模型侧：原生或 <a href="/llm/anyres">AnyRes</a> 分辨率 + 二维位置；<a href="/llm/llava-projector">LLaVA 投影器</a> 浅桥仍可用，但冻 CLIP、低分辨率几乎做不成图标。评测：点击是否落在金标控件内（ScreenSpot），不要用 RefCOCO IoU 代替。规划基准（Mind2Web 等）应与纯 grounding 分列，否则分不清是看错还是计划错。</p>',9)),(e(),d(c,null,{default:i(()=>[p(l,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20SHOT%5B%22%E5%B1%8F%E5%B9%95%E6%88%AA%E5%9B%BE%22%5D%20--%3E%20VIT%5B%22%E9%AB%98%E5%88%86%E8%BE%A8%E7%8E%87%20ViT%22%5D%0A%20%20INS%5B%22%E7%82%B9%E5%87%BB%E6%8C%87%E4%BB%A4%22%5D%20--%3E%20LLM%5B%22LLM%22%5D%0A%20%20VIT%20--%3E%20LLM%0A%20%20LLM%20--%3E%20XY%5B%22%E7%82%B9%E5%87%BB%E5%9D%90%E6%A0%87%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>GUI 定位把语言约束（标签文本、第 n 个、相对「搜索框右侧」）打到细格子上。OCR 能力与分辨率直接决定文本按钮；图标依赖外观与布局关系。语言先验「关闭在右上角」在移动 App 里经常错，必须被像素证据覆盖。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>点对了不等于任务完成：弹窗、延迟、权限会让执行失败。下一课换成图表与表：结构是轴与单元格，不是可点控件。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>GUI 定位是截图像素上的指代，服务点击而不是描述。</li><li>分辨率与 UI 数据比加宽投影更关键。</li><li>ScreenSpot 把文本控件与图标分开报。</li><li>出处：SeeClick；CogAgent。</li></ul>',6))])}const B=t(h,[["render",u]]);export{S as __pageData,B as default};
